"""Printable thermal-style receipts using HTML/CSS with Thai text support."""
from html import escape
from core import money, local_time
from i18n import t as tr, markup, language, menu_name, translated_item_options as item_options
STYLE = '\n.receipt-wrap{background:#efe1cc;padding:26px 16px;border-radius:20px;max-width:520px;margin:16px auto;box-sizing:border-box}\n.dek-receipt{font-family:Tahoma,Arial,sans-serif;color:#222;background:#fff;width:100%;max-width:410px;margin:0 auto;padding:30px 26px;box-sizing:border-box;box-shadow:0 8px 25px #68452022;border-top:5px solid #322820;border-bottom:5px solid #322820}\n.dek-receipt *{box-sizing:border-box}.dek-receipt h2{font-size:29px;text-align:center;letter-spacing:-1px;color:#201a16;margin:12px 0 6px}\n.receipt-label{text-align:center;letter-spacing:3px;font-size:10px;color:#777}.receipt-meta{font-size:11px;line-height:1.8;margin:20px 0 12px;color:#555}\n.receipt-items{width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed}.receipt-items th{font-size:10px;color:#888;border-top:1px dashed #aaa;border-bottom:1px dashed #aaa;text-align:left;padding:10px 0}.receipt-items td{padding:11px 0;border-bottom:1px solid #eee;vertical-align:top;overflow-wrap:anywhere}\n.receipt-items th:last-child,.receipt-items td:last-child{text-align:right;width:94px}.receipt-items small{font-size:10px;color:#888;display:block;margin-top:4px}\n.receipt-total{margin-top:16px;padding-top:12px;border-top:1px dashed #999;font-size:12px}.receipt-total div{display:flex;justify-content:space-between;gap:16px;margin:8px 0}.receipt-total .grand{font-size:23px;font-weight:bold;border-top:2px solid #333;padding-top:14px;margin-top:14px}\n.receipt-thanks{text-align:center;margin-top:25px;font-size:12px;font-weight:bold}.receipt-foot{text-align:center;font-size:9px;color:#888;line-height:1.9;margin-top:12px;overflow-wrap:anywhere}.receipt-ref{text-align:center;letter-spacing:3px;font-family:monospace;font-size:13px;margin-top:15px;padding:10px;background:#f5f5f5}\n.receipt-help{font-family:Tahoma,Arial,sans-serif;text-align:center;font-size:12px;color:#8b735c;margin:18px 0 0}\n@media print{body{background:white!important;margin:0}.receipt-wrap{padding:0;background:white;box-shadow:none}.dek-receipt{box-shadow:none;max-width:80mm;padding:5mm;border-width:0}.receipt-help{display:none}@page{size:auto;margin:8mm}}\n'

def receipt_fragment(order):  # สร้างเนื้อหาใบเสร็จ HTML พร้อม escape ข้อมูลและยอดตามบิลจริง
    rows = ''.join((f"{markup('<tr><td>')}{escape(menu_name(i['name']))}{markup('<small>')}{i['quantity']}{markup(' × ฿')}{money(i['price'])}{markup('</small><small>')}{escape(item_options(i))}{markup('</small></td><td>฿')}{money(i['price'] * i['quantity'])}{markup('</td></tr>')}" for i in order['items']))
    method = tr('เงินสด' if order['payment_method'] == 'cash' else 'QR / โอนเงิน')
    service = tr('สั่งกลับบ้าน · ผู้รับ: ') + escape(order.get('pickup_name', '')) + '<br>'+tr('โทร: ') + escape(order.get('pickup_phone', '')) if order.get('fulfillment') == 'takeaway' else f"{markup('โต๊ะ: ')}{escape(order['table_name'])}{markup(' • ')}{order['guests']}{markup(' ท่าน')}"
    price_note=escape(tr('ราคาต่อรายการรวม VAT 7% แล้ว' if order.get('vat_included',0) else 'ราคาต่อรายการก่อน VAT 7%'))
    return f"""{markup('<style>')}{STYLE}{markup('</style><div class="receipt-wrap"><article class="dek-receipt">\n    <div class="receipt-label">FRESH FROM THE GRILL</div><h2>')}{escape(order['shop_name'])}{markup('</h2>\n    <div class="receipt-label">CASH RECEIPT / ใบเสร็จรับเงิน</div>\n    <div class="receipt-meta">รายการ: #')}{order['id']:06}{markup('<br>')}{service}{markup('<br>\n    ลูกค้า: ')}{escape(order['customer'])}{markup('<br>รับเงินเมื่อ: ')}{local_time(order['paid_at'])}{markup('</div>\n    <table class="receipt-items"><thead><tr><th>รายการอาหาร</th><th>จำนวนเงิน</th></tr></thead><tbody>')}{rows}{markup('</tbody></table>')}{price_note}{markup('\n    <div class="receipt-total"><div><span>ก่อน VAT</span><span>฿')}{money(order['subtotal'])}{markup('</span></div>\n    <div><span>VAT 7%</span><span>฿')}{money(order['vat'])}{markup('</span></div><div class="grand"><span>รวมสุทธิ</span><span>฿')}{money(order['total'])}{markup('</span></div>\n    <div><span>ชำระผ่าน</span><span>')}{method}{markup('</span></div></div><div class="receipt-thanks">THANK YOU • ขอบคุณที่ให้เราดูแลมื้อนี้</div>\n    <div class="receipt-ref">DEK-')}{order['id']:06}{markup('</div><div class="receipt-foot">เก็บไว้เป็นหลักฐานการรับเงิน<br>เอกสารนี้ไม่ใช่ใบกำกับภาษีเต็มรูป</div>\n    </article><div class="receipt-help">เปิดไฟล์แล้วกด Ctrl+P เพื่อพิมพ์หรือบันทึกเป็น PDF</div></div>')}"""

def receipt_html(order):  # ห่อใบเสร็จเป็นเอกสาร UTF-8 สำหรับดาวน์โหลด เปิดและพิมพ์
    return (f"""{markup('<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dek Steak Receipt ')}{order['id']:06}{markup('</title><style>body{background:#f5eee4;margin:0;padding:20px}</style></head><body>')}""" + receipt_fragment(order) + '</body></html>').replace('lang="th"',f'lang="{language()}"').encode('utf-8')